import asyncio

from app.agents.mcp_tools import execute_mcp_tool


# Step 1: Define file creation arguments
arguments = {
    "filename": "aegis_generated.py",
    "content": 'print("Generated by AEGIS through MCP!")'
}


# Step 2: Execute the MCP create_file tool
result = asyncio.run(
    execute_mcp_tool(
        "create_file",
        arguments
    )
)


# Step 3: Display the result
print("MCP Execution Result:")

for item in result.content:
    if hasattr(item, "text"):
        print(item.text)